        // DexibleData struct layout (offset from DexibleStorage key):
        // 0: bool paused
        // 1: uint8 revshareSplitRatio
        // 2: uint16 stdBpsRate
        // 3: uint16 minBpsRate
        // 4: uint112 minFeeUSD
        // 5: ICommunityVault communityVault
        // 6: address treasury
        // 7: address adminMultiSig <-- WE WRITE HERE
        // 8: IDXBL dxblToken
        // 9: IArbitrumGasOracle arbitrumGasOracle
        // 10: IStandardGasAdjustments stdGasAdjustment
        // 11: mapping(address => bool) relays

        bytes32 adminSlot = bytes32(uint256(DEXIBLE_STORAGE_KEY) + 7);

        // Step 1: Set ourselves as adminMultiSig
        assembly {
            sstore(adminSlot, address())
        }

        // ProxyData struct layout (offset from ProxyStorage key):
        // 0: address logic
        // 1: uint32 timelockSeconds
