cat <<'EOF' > src/Target.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.13;

interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

library SafeMath {
    function add(uint256 a, uint256 b) internal pure returns (uint256) { return a + b; }
    function sub(uint256 a, uint256 b) internal pure returns (uint256) { return a - b; }
    function mul(uint256 a, uint256 b) internal pure returns (uint256) { return a * b; }
    function div(uint256 a, uint256 b) internal pure returns (uint256) { return a / b; }
}

abstract contract Context {
    function _msgSender() internal view virtual returns (address) { return msg.sender; }
}

abstract contract Ownable is Context {
    address private _owner;
    constructor() { _owner = msg.sender; }
    modifier onlyOwner() { require(_owner == _msgSender(), "Ownable: caller is not the owner"); _; }
    function owner() public view virtual returns (address) { return _owner; }
}

contract StakingDYNA is Ownable {
    using SafeMath for uint256;
    uint256 public apr = 3200;
    uint256 constant RATE_PRECISION = 10000;
    uint256 constant ONE_YEAR_IN_SECONDS = 365 * 24 * 60 * 60;
    uint256 constant ONE_DAY_IN_SECONDS = 24 * 60 * 60;
    uint256 constant PERIOD_PRECISION = 10000;
    IERC20 public token;
    bool public enabled;
    event Deposit(address indexed user, uint256 amount);
    event Redeem(address indexed user, uint256 amount);
    constructor(IERC20 _token) { token = _token; }
    struct StakeDetail {
        uint256 principal;
        uint256 lastProcessAt;
        uint256 pendingReward;
        uint256 firstStakeAt;
    }
    mapping(address => StakeDetail) public stakers;
    function setEnabled(bool _enabled) external onlyOwner { enabled = _enabled; }
    function updateAPR(uint256 _apr) external onlyOwner { apr = _apr; }
    function emergencyWithdraw(uint256 _amount) external onlyOwner { token.transfer(msg.sender, _amount); }
    function getStakeDetail(address _staker) public view returns (uint256 principal, uint256 pendingReward, uint256 lastProcessAt, uint256 firstStakeAt) {
        StakeDetail memory stakeDetail = stakers[_staker];
        return (stakeDetail.principal, stakeDetail.pendingReward, stakeDetail.lastProcessAt, stakeDetail.firstStakeAt);
    }
    function getInterest(address _staker) public view returns (uint256) {
        StakeDetail memory stakeDetail = stakers[_staker];
        uint256 duration = block.timestamp.sub(stakeDetail.lastProcessAt);
        uint256 interest = stakeDetail.principal.mul(apr).mul(duration).div(ONE_YEAR_IN_SECONDS).div(RATE_PRECISION);
        return interest.add(stakeDetail.pendingReward);
    }
    function deposit(uint256 _stakeAmount) external {
        require(enabled, "Staking is not enabled");
        require(_stakeAmount > 0, "StakingDYNA: stake amount must be greater than 0");
        token.transferFrom(msg.sender, address(this), _stakeAmount);
        StakeDetail storage stakeDetail = stakers[msg.sender];
        if (stakeDetail.firstStakeAt == 0) {
            stakeDetail.principal = stakeDetail.principal.add(_stakeAmount);
            stakeDetail.firstStakeAt = stakeDetail.firstStakeAt == 0 ? block.timestamp : stakeDetail.firstStakeAt;
            stakeDetail.lastProcessAt = block.timestamp;
        } else {
            stakeDetail.principal = stakeDetail.principal.add(_stakeAmount);
        }
        emit Deposit(msg.sender, _stakeAmount);
    }
    function redeem(uint256 _redeemAmount) external {
        require(enabled, "Staking is not enabled");
        StakeDetail storage stakeDetail = stakers[msg.sender];
        require(stakeDetail.firstStakeAt > 0, "StakingDYNA: no stake");
        uint256 interest = getInterest(msg.sender);
        uint256 claimAmount = interest.mul(_redeemAmount).div(stakeDetail.principal);
        uint256 remainAmount = interest.sub(claimAmount);
        stakeDetail.lastProcessAt = block.timestamp;
        require(stakeDetail.principal >= _redeemAmount, "StakingDYNA: redeem amount must be less than principal");
        stakeDetail.principal = stakeDetail.principal.sub(_redeemAmount);
        stakeDetail.pendingReward = remainAmount;
        require(token.transfer(msg.sender, _redeemAmount.add(claimAmount)), "StakingDYNA: transfer failed");
        emit Redeem(msg.sender, _redeemAmount.add(claimAmount));
    }
}
EOF
